    trapExamples: [{ question: "5この ボールを 2つの はこに わけます。1つの はこに 1こ はいって います。もう1つの はこは いくつ？", wrongAnswer: "1こ", trapExplanation: "1つ めの はこと おなじ かずと かんがえた。", correctAnswer: "4こ", correctExplanation: "ぜんぶで 5こ。5から 1を とって 4こ。" }],
