    title: "たしざんカード（こたえが10まで）",
    description: "こたえが 10までの たしざんを、すぐに いえるように する",
    intro: "たしざんは、れんしゅうして おぼえると、すぐに こたえが いえます。「いくつと いくつ」を おぼえている ひとは、もう たくさん しっているよ。",
    keyPoints: ["「いくつと いくつ」を おもいだすと、たしざんの こたえが わかる", "3＋2 と 2＋3 は おなじ こたえ（5）", "カードで れんしゅうして、すぐに いえるように する"],
    sections: [
      { heading: "1. たしざんカードで れんしゅう", body: "■ たしざんカードって なに？\nおもてに「3＋2」、うらに「5」と かいた カードです。見て すぐに こたえが いえるように れんしゅうします。\n\n■ おぼえかた\n「いくつと いくつ」を おもいだします。\n・5は 3と 2 → 3 ＋ 2 ＝ 5\n・7は 4と 3 → 4 ＋ 3 ＝ 7\n\n■ たす じゅんばんを かえても おなじ\n3 ＋ 2 ＝ 5 と 2 ＋ 3 ＝ 5。あかいろと あおいろの かずを いれかえても、ぜんぶで おなじ かずです。\n\n★ ここがポイント：たしざんは「**いくつと いくつ**」を おもいだす。**じゅんばんを かえても こたえは おなじ**。", figureId: "u120e1_023_a" },
      { heading: "2. やってみよう", body: "【なにを きかれているかな】「4 ＋ 3」の こたえを、いくつと いくつを つかって だそう\n\n【なぜ この やりかたかな】7は 4と 3に わけられる ことを、おぼえているから。\n\n【ステップ1】「7は いくつと いくつ」を おもいだす：1と6、2と5、3と4、4と3…\n【ステップ2】4と 3で 7\n【ステップ3】だから 4 ＋ 3 ＝ 7\n\n【こたえ】7\n\n【たしかめ】3 ＋ 4 も 7になる。じゅんばんを かえても おなじ。" },
      { heading: "3. よくある まちがい", body: "■ ゆびを つかって かぞえて しまう\n\nさいしょは ゆびで かぞえても いいです。でも、だんだん「いくつと いくつ」で すぐに いえるように しましょう。\n\n■ なおしかた\n・カードを 5まい ずつ れんしゅう\n・まちがえた カードは あつめて くりかえす\n・こえに だして いう\n\n★ ここがポイント：まちがえた カードを **くりかえし**れんしゅうすると、おぼえられる。" },
      { heading: "4. じぶんの ことばで いってみよう", body: "■ ことばに して みよう（アウトプット）\n・「5 ＋ 2」の こたえを、いくつと いくつを つかって せつめいしてみよう\n・じぶんで たしざんカードを 3まい つくって、おうちの 人と あそんでみよう\n\n■ おうちの人へ\n紙を 切って カードを 一緒に 作ると 楽しく 続けられます。答えを 言えるように なるまで 何度も。\n\n★ ここがポイント：**読むだけでなく、声に出して言う・紙に書く**と、しっかり身につきます。まちがえても大丈夫。「どうしてそう思ったの？」と聞いてあげてください。" },
    ],
    trapExamples: [{ question: "2 ＋ 5 の こたえは？", wrongAnswer: "3", trapExplanation: "ひきざんと まちがえて 5−2 を した。", correctAnswer: "7", correctExplanation: "2 ＋ 5 ＝ 7。「7は 2と 5」と おなじ。たしざんは ふえる けいさん。" }],
