    description: "しきを 見て、たしざんの おはなしを つくる",
    intro: "「3 ＋ 2 ＝ 5」の しきから、どんな おはなしが つくれるかな？ ことばに すると、たしざんの いみが もっとよく わかります。",
    keyPoints: ["しきから おはなしを つくる", "「あわせて」か「ふえると」の どちらかで つくれる", "おはなしを 絵に かくと わかりやすい"],
    sections: [
      { heading: "1. しきから おはなしを つくろう", body: "■ 3 ＋ 2 ＝ 5 の おはなし\n①「**あわせて**」の おはなし\n　あかい りんご 3こと、あおい りんご 2こ。あわせて 5こ。\n②「**ふえると**」の おはなし\n　こうえんに 3にん いました。2にん きました。ぜんぶで 5にん。\n\n■ どっちでも いいの？\nどちらでも だいじょうぶです。**しきは おなじ**でも、おはなしは いろいろ つくれます。\n\n■ なぜ おはなしを つくるの？\nしきの いみが、ほんとうに わかっているか たしかめられるからです。\n\n★ ここがポイント：1つの しきから、**「あわせて」も「ふえると」も** おはなしが つくれる。", figureId: "u120e1_024_a" },
      { heading: "2. やってみよう", body: "【なにを きかれているかな】「4 ＋ 3 ＝ 7」の おはなしを、1つ つくろう\n\n【なぜ この やりかたかな】しきの いみを、ことばで せつめいする れんしゅうだから。\n\n【ステップ1】4と 3は なにの かずか きめる（れい：あめ）\n【ステップ2】「あわせて」の おはなしに する\n【ステップ3】「あめを 4こ もっています。3こ もらいました。ぜんぶで 7こ」\n\n【こたえ】あめを 4こ もっています。3こ もらいました。ぜんぶで 7こ。\n\n【たしかめ】しきに もどして、4 ＋ 3 ＝ 7 に なるか たしかめる。" },
      { heading: "3. よくある まちがい", body: "■ おはなしの かずと しきの かずが ちがう\n\n「4 ＋ 3」の しきなのに、おはなしが 4と 5に なって しまう。\n\n■ なおしかた\nおはなしを つくったら、しきの かずを ぜんぶ つかったか たしかめる。\n\n■ たしざんに ならない おはなし\n「あめを 4こ もっていて、3こ たべました」は、へる おはなし。ひきざんです。\n\n★ ここがポイント：たしざんの おはなしは、**ふえる か あわせる**。へる おはなしでは ありません。" },
      { heading: "4. じぶんの ことばで いってみよう", body: "■ ことばに して みよう（アウトプット）\n・「5 ＋ 2 ＝ 7」の おはなしを つくって、おうちの 人に はなしてみよう\n・おなじ しきで、「あわせて」と「ふえると」の 2つの おはなしを つくってみよう\n\n■ おうちの人へ\nおはなし作りは、思考力を 育てる とても いい 練習です。変な 話でも 笑って 受け止めて あげてください。\n\n★ ここがポイント：**読むだけでなく、声に出して言う・紙に書く**と、しっかり身につきます。まちがえても大丈夫。「どうしてそう思ったの？」と聞いてあげてください。" },
    ],
    trapExamples: [{ question: "「3 ＋ 4 ＝ 7」の おはなしに なっているのは どれ？ ①3こ あって 4こ たべた　②3こ あって 4こ もらった", wrongAnswer: "①", trapExplanation: "「たべた」は へる おはなしなのに、たしざんと かんちがいした。", correctAnswer: "②", correctExplanation: "4こ もらったので ふえる。3 ＋ 4 ＝ 7。①は へる おはなし。" }],
