    intro: "「3 ＋ 2 ＝ 5」と「5 − 2 ＝ 3」。にて いると おもわない？ たしざんと ひきざんは、じつは 1つの なかまなんだよ。",
    keyPoints: ["3＋2＝5 なら、5−2＝3 と 5−3＝2", "たしざんの こたえから ひくと、もとの かずに もどる", "ひきざんの こたえを たしざんで たしかめられる"],
    sections: [
      { heading: "1. たしざんと ひきざんは なかま", body: "■ 3つの かずの なかま\n3、2、5の 3つの かずは、なかまです。\n・3 ＋ 2 ＝ 5\n・2 ＋ 3 ＝ 5\n・5 − 2 ＝ 3\n・5 − 3 ＝ 2\n\n■ なぜ？\n3と 2を あわせて 5。5から 2を とると、もとの 3に もどります。5から 3を とると、もとの 2に もどります。\n\n■ たしかめに つかえる\nひきざんの こたえは、たしざんで たしかめられます。\n5 − 2 ＝ 3 → 3 ＋ 2 ＝ 5 に なれば、せいかい。\n\n★ ここがポイント：**たしざんと ひきざんは なかま**。ひきざんの こたえは **たしざんで たしかめる**。", figureId: "u120e1_030_a" },
      { heading: "2. やってみよう", body: "【なにを きかれているかな】「4 ＋ 3 ＝ 7」から、ひきざんの しきを 2つ つくろう\n\n【なぜ この やりかたかな】たしざんと ひきざんは、おなじ 3つの かずの なかまだから。\n\n【ステップ1】3つの かずは、4、3、7\n【ステップ2】7から 3を ひくと 4\n【ステップ3】7から 4を ひくと 3\n\n【こたえ】7 − 3 ＝ 4 と 7 − 4 ＝ 3\n\n【たしかめ】それぞれ たしざんに もどして、4＋3＝7 に なるか たしかめる。" },
      { heading: "3. よくある まちがい", body: "■ かずを とりちがえる\n\n「4＋3＝7」から「7−4＝3」を つくる とき、「3−7」と かいてしまう まちがいです。\n\n■ なおしかた\nひきざんは、いつも **いちばん おおきい かず（ぜんぶ）**から ひく。\n\n★ ここがポイント：ひきざんは **ぜんぶ**から ひく。ぜんぶは、たしざんの こたえ。" },
      { heading: "4. じぶんの ことばで いってみよう", body: "■ ことばに して みよう（アウトプット）\n・「2 ＋ 5 ＝ 7」から、ひきざんの しきを 2つ つくって、いってみよう\n・ひきざんの こたえを、たしざんで たしかめる やりかたを、せつめいしてみよう\n\n■ おうちの人へ\n3 つの 数の「家族」で 考えさせると、足し算・引き算が つながって 見えます。\n\n★ ここがポイント：**読むだけでなく、声に出して言う・紙に書く**と、しっかり身につきます。まちがえても大丈夫。「どうしてそう思ったの？」と聞いてあげてください。" },
    ],
    trapExamples: [{ question: "2 ＋ 5 ＝ 7 の なかまの ひきざんは どれ？ ①7−5＝2　②5−7＝2", wrongAnswer: "②", trapExplanation: "ひく じゅんばんを まちがえた。", correctAnswer: "①（7 − 5 ＝ 2）", correctExplanation: "ひきざんは ぜんぶ（7）から ひく。7−5＝2、7−2＝5。" }],
