    sections: [
      { heading: "1. すうじを 2つ ならべる", body: "■ 10より おおきい かず\n13は「10と 3」。ひだりに「1」（10の たば が 1つ）、みぎに「3」（ばらが 3こ）と かきます。\n**13**\n\n■ 10と 20\n・10は 10の たばが 1つ、ばらが 0こ → **10**\n・20は 10の たばが 2つ、ばらが 0こ → **20**\n\n■ なぜ ならべて かくの？\nひだりの すうじで 10の たばの かず、みぎの すうじで ばらの かずを あらわすと、どんなに おおきな かずでも すうじで かけるからです。\n\n★ ここがポイント：**ひだりの すうじは 10の たば、みぎの すうじは ばら**。", figureId: "u120e1_033_a" },
      { heading: "2. やってみよう", body: "【なにを きかれているかな】10の たばが 1つと、ばらが 8こ あります。すうじで かこう\n\n【なぜ この やりかたかな】ひだりに 10の たばの かず、みぎに ばらの かずを かくから。\n\n【ステップ1】10の たばは 1つ → ひだりに 1\n【ステップ2】ばらは 8こ → みぎに 8\n【ステップ3】ならべて かく\n\n【こたえ】18\n\n【たしかめ】10と 8で 18。かぞえて たしかめる。" },
      { heading: "3. よくある まちがい", body: "■ ひだりと みぎを ぎゃくに かく\n\n「18」を「81」と かいてしまう まちがいです。\n\n■ なおしかた\n・10の たばを さきに かく\n・「1と 8」ではなく「10と 8」と おもいうかべる\n\n■ 0の かきわすれ\n「20」を「2」と かいてしまう ことも。ばらが 0こでも「0」を かく。\n\n★ ここがポイント：**10の たばを ひだり、ばらを みぎ**。0も かく。" },
      { heading: "4. じぶんの ことばで いってみよう", body: "■ ことばに して みよう（アウトプット）\n・11から 20まで、声に だして よみながら、すうじを かいてみよう\n・「ひだりの すうじは なにを あらわすか」を、じぶんの ことばで いってみよう\n\n■ おうちの人へ\n「18」と「81」を 逆に 書く 間違いは 小1で よく あります。10の たばを 先に 置くことを 繰り返し 教えてください。\n\n★ ここがポイント：**読むだけでなく、声に出して言う・紙に書く**と、しっかり身につきます。まちがえても大丈夫。「どうしてそう思ったの？」と聞いてあげてください。" },
    ],
