    intro: "りんごが 5こ あります。3こ もらって、2こ たべました。いまは なんこ？ たしざんと ひきざんが まざって いても、ひだりから じゅんに けいさんします。",
    keyPoints: ["ひだりから じゅんに、たす・ひく を する", "5＋3−2 は、5＋3＝8、8−2＝6", "ふえる・へる の ことばを 見わける"],
    sections: [
      { heading: "1. たしざんと ひきざんが まざった 3つの かずの やりかた", body: "■ たしざんと ひきざんが まざった けいさん\n5 ＋ 3 − 2 を けいさんします。\n① まず ひだりの 2つ：5 ＋ 3 ＝ 8\n② つぎに 8から 2を ひく：8 − 2 ＝ 6\n\nこたえは **6**です。\n\n■ なぜ ひだりから？\nおはなしの じゅんばんに したがって けいさんするからです。「もらった」は ふえる、「たべた」は へる。\n\n■ ことばの めじるし\n・ふえる、もらう、あわせる → ＋\n・へる、たべる、あげる → −\n\n★ ここがポイント：**ひだりから じゅんに**。**ふえる は ＋、へる は −**。", figureId: "u120e1_039_a" },
      { heading: "2. やってみよう", body: "【なにを きかれているかな】りんごが 5こ あります。3こ もらって、2こ たべました。いまは なんこ？\n\n【なぜ この やりかたかな】おはなしの じゅんに、ふえる・へる を けいさんするから。\n\n【ステップ1】はじめは 5こ。3こ もらって ふえる：5 ＋ 3 ＝ 8\n【ステップ2】2こ たべて へる：8 − 2 ＝ 6\n\n【こたえ】5 ＋ 3 − 2 ＝ 6（6こ）\n\n【たしかめ】6 ＋ 2 − 3 ＝ 5。はじめの かずに もどる。" },
      { heading: "3. よくある まちがい", body: "■ ＋と − を まちがえる\n\nおはなしを よまずに、しきだけ 見て けいさんして、まちがえる ことが あります。\n\n■ なおしかた\n・おはなしの ことばを 見て、ふえるか へるか きめる\n・1つ けいさんしたら こたえを かきとめる\n\n★ ここがポイント：**ふえる か へる か**を ことばで たしかめる。" },
      { heading: "4. じぶんの ことばで いってみよう", body: "■ ことばに して みよう（アウトプット）\n・「5 ＋ 3 − 2」の おはなしを つくって、おうちの 人に はなしてみよう\n・ふえる ことばと、へる ことばを、5つずつ いってみよう\n\n■ おうちの人へ\nお話を 作ると、足し算・引き算の 意味が 定着します。\n\n★ ここがポイント：**読むだけでなく、声に出して言う・紙に書く**と、しっかり身につきます。まちがえても大丈夫。「どうしてそう思ったの？」と聞いてあげてください。" },
    ],
    trapExamples: [{ question: "4 ＋ 3 − 2 は いくつ？", wrongAnswer: "9", trapExplanation: "「−2」を「＋2」と まちがえて 4＋3＋2を した。", correctAnswer: "5", correctExplanation: "4＋3＝7、7−2＝5。−は ひく。" }],
