    intro: "30 ＋ 20 は いくつ？ 10の たばが 3つと 2つで、ぜんぶで 5つ。10の たばで かんがえると かんたんだよ。",
    keyPoints: ["何十どうしの たしざんは、10の たばの かずを たす", "10の たばを 1つの かずと して かんがえる", "10の たばの かずを けいさんして、10ばいに する"],
    sections: [
      { heading: "1. 何十の たしざん", body: "■ 10の たばで かんがえる\n30 ＋ 20 を かんがえます。\n・30 は 10の たばが 3つ\n・20 は 10の たばが 2つ\n\n10の たばの かずを けいさんして、あとで「10」を つけます。\n3 ＋ 2 ＝ 5 → **50**\n\n■ なぜ これで いいの？\n10の たばを 1つの かたまりと みると、かずが 小さくて けいさんしやすいからです。\n\n■ ほかの れい\n・20 ＋ 40 ＝ 60（2 ＋ 4 ＝ 6）\n・50 ＋ 30 ＝ 80（5 ＋ 3 ＝ 8）\n\n★ ここがポイント：**10の たばの かず**を けいさんして、さいごに **10を つける**。", figureId: "u120e1_073_a" },
      { heading: "2. やってみよう", body: "【なにを きかれているかな】30 ＋ 20 を、10の たばで けいさんしよう\n\n【なぜ この やりかたかな】10の たばの かずだけを けいさんすれば よいから。\n\n【ステップ1】30は 10の たばが 3つ、20は 2つ\n【ステップ2】3 ＋ 2 ＝ 5\n【ステップ3】10の たばが 5つ → 50\n\n【こたえ】30 ＋ 20 ＝ 50\n\n【たしかめ】50 − 20 ＝ 30 と もどる。" },
      { heading: "3. よくある まちがい", body: "■ 0を つけわすれる\n\n3 ＋ 2 ＝ 5 の あと、10を つけわすれて「5」と こたえる まちがい。\n\n■ なおしかた\n・10の たばの かずを けいさんしたら、**10を つける**\n・たしかめ：50 を 10の たばの かずに もどす\n\n★ ここがポイント：こたえに **0を つける**ことを わすれない。" },
      { heading: "4. じぶんの ことばで いってみよう", body: "■ ことばに して みよう（アウトプット）\n・「30 ＋ 20」を、10の たばで せつめいしてみよう\n・「30 ＋ 20」と「3 ＋ 2」の にている ところを、いってみよう\n\n■ おうちの人へ\n10 の たばの 絵を 描いて、数える 練習を してみてください。\n\n★ ここがポイント：**読むだけでなく、声に出して言う・紙に書く**と、しっかり身につきます。まちがえても大丈夫。「どうしてそう思ったの？」と聞いてあげてください。" },
    ],
    trapExamples: [{ question: "30 ＋ 20 は いくつ？", wrongAnswer: "5", trapExplanation: "10の たばの かずだけを こたえて、10を つけわすれた。", correctAnswer: "50", correctExplanation: "10の たばが 5つなので 50。" }],
